// Globalen Zwischenspeicher für diesen Lauf leeren (überlebt über alle Loop-Iterationen hinweg)
const staticData = $getWorkflowStaticData('global');
staticData.files = [];

// Alle Zeilen nach Kundennummer gruppieren -> ein Item pro Kunde mit Rechnungszeilen-Array
const rows = $input.all().map(i => i.json);
const grouped = {};

for (const r of rows) {
  const key = r.Kundennummer;
  if (!grouped[key]) grouped[key] = [];
  grouped[key].push(r);
}

return Object.entries(grouped).map(([kundennummer, items]) => {
  // älteste (früheste) Fälligkeit unter den ÜBERFÄLLIGEN Rechnungen dieses Kunden ermitteln
  const ueberfaellige = items.filter(i => i.Faelligkeitsstatus === 'überfällig' && i.Faelligkeitsdatum);
  let aeltesteFaelligkeit = null;
  if (ueberfaellige.length > 0) {
    aeltesteFaelligkeit = ueberfaellige.reduce((min, i) => {
      const d = new Date(i.Faelligkeitsdatum);
      return (min === null || d < min) ? d : min;
    }, null);
  }

  return {
    json: {
      kundennummer,
      firma: items[0].Firma,
      anzahlRechnungen: items.length,
      summeOffen: items.reduce((sum, i) => sum + (Number(i.OffenerBetrag) || 0), 0),
      aeltesteFaelligkeitUeberfaellig: aeltesteFaelligkeit ? aeltesteFaelligkeit.toISOString() : null,
      items
    }
  };
});

// Rechnungszeilen des aktuellen Kunden wieder in einzelne Items auflösen,
// damit "Convert to File" daraus eine Zeile pro Rechnung macht.
return $json.items.map(row => ({
  json: {
    Rechnungsnummer: row.Rechnungsnummer,
    Rechnungsdatum: row.Rechnungsdatum,
    Rechnungsbetrag: row.Rechnungsbetrag,
    OffenerBetrag: row.OffenerBetrag,
    Faelligkeitsdatum: row.Faelligkeitsdatum,
    TageUeberfaellig: row.TageUeberfaellig,
    Faelligkeitsstatus: row.Faelligkeitsstatus,
    Mahnstufe: row.Mahnstufe
  }
}));

// Erzeugte Datei dieses Kunden im GLOBALEN Zwischenspeicher ablegen,
// damit nach der Schleife alle Dateien zusammen in einer Mail verschickt werden können.
const staticData = $getWorkflowStaticData('global');
if (!staticData.files) staticData.files = [];

const bin = $input.first().binary.data;
const kunde = $('Pro Kunde durchlaufen').item.json;

staticData.files.push({
  fileName: bin.fileName,
  mimeType: bin.mimeType,
  data: bin.data,
  kundennummer: kunde.kundennummer,
  firma: kunde.firma,
  anzahlRechnungen: kunde.anzahlRechnungen,
  summeOffen: kunde.summeOffen,
  aeltesteFaelligkeitUeberfaellig: kunde.aeltesteFaelligkeitUeberfaellig
});

return [{ json: { kundennummer: kunde.kundennummer } }];

// Läuft erst, wenn die Schleife komplett durch ist ("done"-Ausgang von Split In Batches).
// Baut aus dem GLOBALEN Zwischenspeicher EIN Item: alle Excel-Dateien als Anhänge + HTML-Tabelle als Zusammenfassung.
const staticData = $getWorkflowStaticData('global');
const files = staticData.files || [];

const binaryData = {};
files.forEach((f, idx) => {
  binaryData[`file_${idx}`] = {
    data: f.data,
    fileName: f.fileName,
    mimeType: f.mimeType
  };
});

const fmtDatum = (iso) => {
  if (!iso) return '–';
  const d = new Date(iso);
  return d.toLocaleDateString('de-DE');
};
const fmtEuro = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';

const zeilenHtml = files.map(f => `
  <tr>
    <td>${f.kundennummer}</td>
    <td>${f.firma}</td>
    <td style="text-align:right">${f.anzahlRechnungen}</td>
    <td style="text-align:right">${fmtEuro(f.summeOffen)}</td>
    <td>${fmtDatum(f.aeltesteFaelligkeitUeberfaellig)}</td>
  </tr>`).join('');

const tabelleHtml = `
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; font-family:Arial, sans-serif; font-size:13px;">
  <thead>
    <tr style="background:#f0f0f0;">
      <th>Kundennummer</th>
      <th>Kunde</th>
      <th>Anzahl offener Rechnungen</th>
      <th>Offener Posten (Summe)</th>
      <th>Fälligkeit älteste überfällige Rechnung</th>
    </tr>
  </thead>
  <tbody>${zeilenHtml}</tbody>
</table>`;

const summeGesamt = files.reduce((s, f) => s + f.summeOffen, 0);

const result = {
  json: {
    anzahlKunden: files.length,
    summeGesamt,
    tabelleHtml
  },
  binary: binaryData
};

staticData.files = []; // Zwischenspeicher für den nächsten Lauf leeren

return [result];

// Erzeugte Datei dieses Kunden im GLOBALEN Zwischenspeicher ablegen,
// damit nach der Schleife alle Dateien zusammen in einer Mail verschickt werden können.
//
// WICHTIG (n8n Cloud): binary.data.data ist auf Cloud nur eine interne Dateisystem-Referenz,
// kein eingebettetes Base64. Deshalb muss der echte Inhalt über getBinaryDataBuffer geholt werden.
const staticData = $getWorkflowStaticData('global');
if (!staticData.files) staticData.files = [];

const bin = $input.first().binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const kunde = $('Pro Kunde durchlaufen1').item.json;

staticData.files.push({
  fileName: bin.fileName,
  mimeType: bin.mimeType,
  data: buffer.toString('base64'),
  kundennummer: kunde.kundennummer,
  firma: kunde.firma,
  anzahlRechnungen: kunde.anzahlRechnungen,
  summeOffen: kunde.summeOffen,
  anzahlUeberfaellig: kunde.anzahlUeberfaellig,
  summeUeberfaellig: kunde.summeUeberfaellig,
  aeltesteFaelligkeitUeberfaellig: kunde.aeltesteFaelligkeitUeberfaellig
